-- 5. RELASIKAN KELAS_ID SANTRI DENGAN MASTER KELAS
UPDATE santri s
JOIN kelas k ON s.nama_kelas = k.nama_kelas
SET s.kelas_id = k.id;

-- 6. TAHUN MASUK DEFAULT
UPDATE santri
SET tahun_masuk = '2026/2027'
WHERE tahun_masuk IS NULL OR tahun_masuk = '';

-- 7. SET FINGERPRINT PIN DI MESIN SESUAI ID SANTRI (BUKAN NIS ATAU NISN)
UPDATE santri
SET fingerprint_pin = CAST(id AS CHAR);
